quests[10733] = { id = 10733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Down the Violet Path", description = "You've chosen your path, {class}.  Now it is up to you to travel the path to wherever it may lead.\n\nYou will find that having friends among the Archmages of Dalaran has its advantages.  Serve us well and your deeds will not go unrewarded.", progress = "It is good to see you again, {name}.", completion = "You honor us with your service, {name}. Behold as I unleash the power contained in your signet!", objectives = "Bring your Violet Signet to Archmage Leryda at Deadwind Pass after obtaining Honored reputation with the Violet Eye.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
